// Normalise to Piccolo's lead shape and apply the keyword/region/grade
// filter from artboard P2-02. Adjust the keyword list to match your
// current SA_Tender_Platforms_Reference.
const KEYWORDS = ['road maintenance','road rehabilitation','reseal','asphalt','bitumen','cold mix','hot mix','paving','patching','pothole repair','surfacing','civil works','earthworks','stormwater','culvert','drainage'];
const PLATFORM_ID = 'REPLACE-WITH-PLATFORM-UUID-FROM-PICCOLO';

const seen = new Set();
const out = [];
for (const item of items) {
  const title = (item.json.title || '').toString();
  const summary = (item.json.contentSnippet || item.json.content || '').toString();
  const haystack = (title + ' ' + summary).toLowerCase();
  const matches = KEYWORDS.some((k) => haystack.includes(k));
  if (!matches) continue;

  // Dedupe within this run on title (the real dedupe-on-hash of tender
  // number + client happens server-side via the DB unique index; this is
  // just to avoid posting the same RSS entry twice in one poll).
  const key = title.trim().toLowerCase();
  if (seen.has(key)) continue;
  seen.add(key);

  out.push({
    json: {
      tenderNo: (item.json.guid || item.json.link || title).toString().slice(0, 120),
      client: 'Unknown, from RSS - confirm on capture',
      title: title.slice(0, 500),
      closingAt: item.json.isoDate || new Date(Date.now() + 21 * 86400000).toISOString(),
      sourcePlatformId: PLATFORM_ID,
    },
  });
}
return out;
